import React, { useEffect, useRef, useState } from 'react';
import { View, Image, StyleSheet, Animated, Easing, Text } from 'react-native';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from '../services/firebaseConfig';
import { LinearGradient } from 'expo-linear-gradient';

export default function SplashLogoScreen({ navigation }: any) {
  const opacity = useRef(new Animated.Value(0)).current;
  const progress = useRef(new Animated.Value(0)).current;
  const [percentage, setPercentage] = useState(0);

  useEffect(() => {
    // Animação da logo
    Animated.timing(opacity, {
      toValue: 1,
      duration: 600,
      useNativeDriver: true,
    }).start();

    // Animação da barra de progresso
    const progressAnimation = Animated.timing(progress, {
      toValue: 1,
      duration: 2500,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: false,
    });

    // ✅ CORREÇÃO: Atualiza a porcentagem a cada mudança do progresso
    const updatePercentage = (dado: { value: number }) => {
      setPercentage(Math.floor(dado.value * 100));
    };
    progress.addListener(updatePercentage); // Passa a função com o parâmetro do valor

    progressAnimation.start();

    // Verificação Firebase e navegação
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setTimeout(() => {
        if (user && user.emailVerified) {
          navigation.replace('Inicio');
        } else {
          navigation.replace('Login');
        }
      }, 2800); // Espera a barra terminar
    });

    return () => {
      progress.removeListener(updatePercentage); // Remove o listener corretamente
      unsubscribe();
    };
  }, [navigation, opacity, progress]);

  const widthInterpolate = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });

  return (
    <View style={styles.container}>
      <Animated.Image
        source={require('../assets/logo.png')}
        style={[styles.logo, { opacity }]}
        resizeMode="contain"
      />

      {/* Barra de progresso */}
      <View style={styles.progressBarContainer}>
        <Animated.View style={[styles.progressBar, { width: widthInterpolate }]}>
          <LinearGradient
            colors={['#0099FF', '#00EEFF', '#0066CC']}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.barGradient}
          />
          {/* Efeito de brilho deslizante */}
          <Animated.View
            style={[styles.shineEffect, {
              transform: [{ translateX: progress.interpolate({
                inputRange: [0, 1],
                outputRange: [-40, 260]
              }) }]
            }]}
          />
        </Animated.View>
      </View>

      {/* Círculo com porcentagem */}
      <LinearGradient
        colors={['#0099FF', '#00EEFF', '#0066CC']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.circle}
      >
        <Text style={styles.percentageText}>{percentage}%</Text>
      </LinearGradient>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#18182a',
    justifyContent: 'center',
    alignItems: 'center',
  },
  logo: {
    width: 180,
    height: 180,
    marginBottom: 40,
  },
  progressBarContainer: {
    width: 260,
    height: 16,
    borderRadius: 8,
    backgroundColor: '#1a1a35',
    overflow: 'hidden',
    borderWidth: 1.5,
    borderColor: 'rgba(0, 200, 255, 0.4)',
    shadowColor: '#00AAFF',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.6,
    shadowRadius: 12,
  },
  progressBar: {
    height: '100%',
    borderRadius: 8,
    position: 'relative',
  },
  barGradient: {
    width: '100%',
    height: '100%',
    borderRadius: 8,
  },
  shineEffect: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: 60,
    height: '100%',
    backgroundColor: 'rgba(255, 255, 255, 0.35)',
    borderRadius: 8,
  },
  circle: {
    marginTop: 20,
    width: 70,
    height: 70,
    borderRadius: 35,
    justifyContent: 'center',
    alignItems: 'center',
    shadowColor: '#00CCFF',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.8,
    shadowRadius: 15,
    elevation: 10,
  },
  percentageText: {
    color: '#FFFFFF',
    fontSize: 22,
    fontWeight: 'bold',
    textShadowColor: 'rgba(0, 80, 150, 0.8)',
    textShadowOffset: { width: 1, height: 1 },
    textShadowRadius: 3,
  },
});