// Componente da Barra de Navegação Global
const BarraNavegacaoFixa = () => {
  const navegacao = useNavigation();
  const rotaAtual = useRoute().name;

  // Animações para cada item
  const animacoes = useRef(
    ITEMS_BARRA.map(() => ({
      escala: new Animated.Value(1),
      opacidade: new Animated.Value(0.6),
      deslocamento: new Animated.Value(0),
    }))
  ).current;

  // Atualiza animações quando mudar a tela
  useEffect(() => {
    ITEMS_BARRA.forEach((item, idx) => {
      const selecionado = item.rota === rotaAtual;
      Animated.parallel([
        Animated.spring(animacoes[idx].escala, {
          toValue: selecionado ? 1.15 : 1,
          useNativeDriver: true,
          speed: 40,
          bounciness: 2,
        }),
        Animated.timing(animacoes[idx].opacidade, {
          toValue: selecionado ? 1 : 0.6,
          duration: 200,
          useNativeDriver: true,
        }),
        Animated.timing(animacoes[idx].deslocamento, {
          toValue: selecionado ? -4 : 0,
          duration: 250,
          useNativeDriver: true,
        }),
      ]).start();
    });
  }, [rotaAtual, animacoes]);

  // Não mostra a barra na tela de abertura
  if (rotaAtual === 'SplashLogo') return null;

  return (
    <View style={estilos.barraNavegacao}>
      {ITEMS_BARRA.map((item, idx) => {
        const selecionado = item.rota === rotaAtual;
        return (
          <TouchableOpacity
            key={item.id}
            style={estilos.itemBarra}
            activeOpacity={0.8}
            onPress={() => navegacao.navigate(item.rota as never)}
          >
            {/* Fundo gradiente animado */}
            <Animated.View
              style={[
                estilos.containerIcone,
                {
                  transform: [
                    { scale: animacoes[idx].escala },
                    { translateY: animacoes[idx].deslocamento },
                  ],
                  opacity: animacoes[idx].opacidade,
                },
              ]}
            >
              <LinearGradient
                colors={item.gradiente}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={[
                  estilos.fundoIcone,
                  selecionado && estilos.fundoIconeAtivo,
                ]}
              >
                {item.icone}
              </LinearGradient>
            </Animated.View>

            {/* Rótulo com animação */}
            <Animated.Text
              style={[
                estilos.rotulo,
                {
                  color: selecionado ? item.gradiente[0] : '#9CA3AF',
                  fontWeight: selecionado ? '700' : '500',
                  opacity: animacoes[idx].opacidade,
                },
              ]}
            >
              {item.rotulo}
            </Animated.Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
};

